package nl.giejay.android.tv.immich.map

import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * The coastlines and country borders the map draws when zoomed in, from res/raw/world_land_50m.bin and
 * world_borders_50m.bin (generated by tools/map/make_world_vectors.py from the public domain Natural Earth 1:50m data;
 * keep the layout in sync with that script).
 */
object WorldVectors {
    /**
     * Repeated parts: a uint16 point count, then that many (int16 longitude, int16 latitude) pairs in hundredths of a
     * degree, little endian. Each part comes back as lon, lat, lon, lat ... in degrees.
     */
    fun parse(bytes: ByteArray): List<FloatArray> {
        val buffer = ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN)
        val parts = ArrayList<FloatArray>()
        while (buffer.remaining() >= 2) {
            val count = buffer.short.toInt() and 0xFFFF
            if (buffer.remaining() < count * 4) break // a cut off file: keep what is whole
            val part = FloatArray(count * 2)
            for (i in 0 until count) {
                part[i * 2] = buffer.short / 100f
                part[i * 2 + 1] = buffer.short / 100f
            }
            parts += part
        }
        return parts
    }
}
